241	type parsedSample struct {
242		name   string
243		ts     int64
244		value  float64
245		labels map[string]string
246	}
247	
248	// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
249	// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
250	func parseSample(raw json.RawMessage) (parsedSample, error) {
251		var p parsedSample
252		p.labels = map[string]string{}
253		dec := json.NewDecoder(bytes.NewReader(raw))
254		dec.UseNumber()
255	
256		tok, err := dec.Token()
257		if err != nil {
258			return p, err
259		}
260		if d, ok := tok.(json.Delim); !ok || d != '{' {
261			return p, fmt.Errorf("each sample must be a JSON object")
262		}
263	
264		present := make(map[string]bool)
265		for dec.More() {
266			keyTok, err := dec.Token()
267			if err != nil {
268				return p, err
269			}
270			key := keyTok.(string)
271			switch key {
272			case "name", "timestamp", "value", "labels":
273			default:
274				return p, fmt.Errorf("unknown field %q", key)
275			}
276			if present[key] {
277				return p, fmt.Errorf("duplicate field %q", key)
278			}
279			present[key] = true
280	
281			switch key {
282			case "name":
283				t, err := dec.Token()
284				if err != nil {
285					return p, err
286				}
287				s, ok := t.(string)
288				if !ok {
289					return p, fmt.Errorf(`field "name" must be a string`)
290				}
291				if s == "" {
292					return p, fmt.Errorf(`field "name" must be a non-empty string`)
293				}
294				p.name = s
295			case "timestamp":
296				n, err := nextJSONNumber(dec, "timestamp")
297				if err != nil {
298					return p, err
299				}
300				v, err := parseJSONInt(n)
301				if err != nil {
302					return p, fmt.Errorf(`field "timestamp": %s`, err)
303				}
304				p.ts = v
305			case "value":
306				n, err := nextJSONNumber(dec, "value")
307				if err != nil {
308					return p, err
309				}
310				v, err := parseFiniteFloat(n)
311				if err != nil {
312					return p, fmt.Errorf(`field "value": %s`, err)
313				}
314				p.value = v
315			case "labels":
316				labels, err := parseLabels(dec, `field "labels" must be an object of string keys to string values`)
317				if err != nil {
318					return p, err
319				}
320				p.labels = labels
321			}
322		}
323		if _, err := dec.Token(); err != nil { // 消耗 '}'
324			return p, err
325		}
326		if _, err := dec.Token(); err != io.EOF {
327			if err == nil {
328				return p, fmt.Errorf("unexpected content after the sample object")
329			}
330			return p, err
331		}
332	
333		for _, field := range []string{"name", "timestamp", "value"} {
334			if !present[field] {
335				return p, fmt.Errorf("missing required field %q", field)
336			}
337		}
338		return p, nil
339	}
340	
341	// parseLabels 从 dec 读取一个标签对象并做统一校验：必须是 JSON 对象
342	// （否则返回调用方给出的 notObjectMsg，写入与查询措辞不同），键为非空字符串、
343	// 值为字符串（空串合法，键值均不做清理），重复键一律拒绝。
344	// 返回的集合不含标签时也是非 nil 的空 map，与省略 labels 的语义一致。
345	func parseLabels(dec *json.Decoder, notObjectMsg string) (map[string]string, error) {
346		t, err := dec.Token()
347		if err != nil {
348			return nil, err
349		}
350		d, ok := t.(json.Delim)
351		if !ok || d != '{' {
352			return nil, fmt.Errorf("%s", notObjectMsg)
353		}
354		labels := map[string]string{}
355		for dec.More() {
356			labelKeyTok, err := dec.Token()
357			if err != nil {
358				return nil, err
359			}
360			labelKey := labelKeyTok.(string)
361			if labelKey == "" {
362				return nil, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
363			}
364			valTok, err := dec.Token()
365			if err != nil {
366				return nil, err
367			}
368			labelVal, ok := valTok.(string)
369			if !ok {
370				return nil, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
371			}
372			if _, dup := labels[labelKey]; dup {
373				return nil, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
374			}
375			labels[labelKey] = labelVal
376		}
377		if _, err := dec.Token(); err != nil { // 消耗 '}'
378			return nil, err
379		}
380		return labels, nil
381	}
382	
383	func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
384		t, err := dec.Token()
385		if err != nil {
386			return "", err
387		}
388		n, ok := t.(json.Number)
389		if !ok {
390			return "", fmt.Errorf(`field %q must be a JSON number`, field)
391		}
392		return n, nil
393	}
394	
395	func parseJSONInt(n json.Number) (int64, error) {
396		s := string(n)
397		if !jsonIntegerRE.MatchString(s) {
398			return 0, fmt.Errorf("must be a JSON integer in milliseconds")
399		}
400		v, err := strconv.ParseInt(s, 10, 64)
401		if err != nil {
402			return 0, fmt.Errorf("must be within int64 range")
403		}
404		return v, nil
405	}
406	
407	func parseFiniteFloat(n json.Number) (float64, error) {
408		s := string(n)
409		if !jsonNumberRE.MatchString(s) {
410			return 0, fmt.Errorf("must be a JSON number")
411		}
412		v, err := strconv.ParseFloat(s, 64)
413		if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
414			return 0, fmt.Errorf("must be a finite number representable as float64")
415		}
416		return v, nil
417	}
