419	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
420	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
421		type pending struct {
422			id  seriesID
423			ref SeriesRef
424			ts  int64
425			val float64
426		}
427	
428		added := 0
429		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
430		seen := make(map[seriesID]map[int64]float64)
431		// 仅记录需要落盘的新增点；校验全部通过后才提交。
432		commits := make([]pending, 0, len(items))
433	
434		failAt := func(index int, msg string) *LineError {
435			return &LineError{Status: "error", Index: index, Error: msg}
436		}
437		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
438			return &LineError{
439				Status: "error",
440				Index:  index,
441				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
442					ref, ts, formatFloat(existing), formatFloat(submitted)),
443				Conflict: &Conflict{
444					// 标签必须复制：冲突结果是本次失败的独立记录，
445					// 调用方修改它不能改动已存序列的身份。
446					Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
447					Timestamp: ts,
448					Existing:  existing,
449					Submitted: submitted,
450				},
451			}
452		}
453	
454		for i, item := range items {
455			pos := i + 1
456			p, err := parseSample(item)
457			if err != nil {
458				return nil, failAt(pos, err.Error())
459			}
460	
461			id := makeSeriesID(p.name, p.labels)
462			ref := SeriesRef{Name: p.name, Labels: p.labels}
463	
464			if byTS, ok := seen[id]; ok {
465				if old, ok := byTS[p.ts]; ok {
466					if old != p.value {
467						return nil, conflictAt(pos, ref, p.ts, old, p.value)
468					}
469					// 同批内重复出现且数值相同：重复，成功忽略。
470					continue
471				}
472			}
473			if sr, ok := s.series[id]; ok {
474				if old, ok := sr.points[p.ts]; ok {
475					if old != p.value {
476						return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
477					}
478					// 与此前批次已写入的值相同：重复，成功忽略。
479					if seen[id] == nil {
480						seen[id] = map[int64]float64{}
481					}
482					seen[id][p.ts] = p.value
483					continue
484				}
485			}
486	
487			added++
488			if seen[id] == nil {
489				seen[id] = map[int64]float64{}
490			}
491			seen[id][p.ts] = p.value
492			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
493		}
494	
495		// 全部采样点合法且无冲突，原子提交本批新增点。
496		for _, c := range commits {
497			sr := s.series[c.id]
498			if sr == nil {
499				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
500				s.series[c.id] = sr
501			}
502			sr.points[c.ts] = c.val
503		}
504	
505		return s.snapshot(added, len(items)-added), nil
506	}
507	
508	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
509	func formatFloat(v float64) string {
510		return strconv.FormatFloat(v, 'g', -1, 64)
511	}
512	
513	type parsedQuery struct {
514		name   string
515		start  int64
516		end    int64
517		labels map[string]string
518	}
519	
520	// queryFromObject 严格解析查询对象并执行只读区间均值查询。
521	func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
522		q, err := parseQuery(raw)
523		if err != nil {
524			return nil, &LineError{Status: "error", Error: err.Error()}
525		}
526		if q.start > q.end {
527			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
528				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
529		}
530		return s.runQuery(q), nil
531	}
532	
533	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
534	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
535	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
536		var q parsedQuery
537		dec := json.NewDecoder(bytes.NewReader(raw))
538		dec.UseNumber()
539	
540		tok, err := dec.Token()
541		if err != nil {
542			return q, err
543		}
544		if d, ok := tok.(json.Delim); !ok || d != '{' {
545			return q, fmt.Errorf("each query must be a JSON object")
546		}
547	
548		present := make(map[string]bool)
549		for dec.More() {
550			keyTok, err := dec.Token()
551			if err != nil {
552				return q, err
553			}
554			key := keyTok.(string)
555			switch key {
556			case "op", "name", "start", "end", "labels":
557			default:
558				return q, fmt.Errorf("unknown field %q", key)
559			}
560			if present[key] {
561				return q, fmt.Errorf("duplicate field %q", key)
562			}
563			present[key] = true
564	
565			switch key {
566			case "op":
567				t, err := dec.Token()
568				if err != nil {
569					return q, err
570				}
571				op, ok := t.(string)
572				if !ok {
573					return q, fmt.Errorf(`field "op" must be a string`)
574				}
575				if op != "query" {
576					return q, fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
577				}
578			case "name":
579				t, err := dec.Token()
580				if err != nil {
581					return q, err
582				}
583				name, ok := t.(string)
584				if !ok {
585					return q, fmt.Errorf(`field "name" must be a string`)
586				}
587				if name == "" {
588					return q, fmt.Errorf(`field "name" must be a non-empty string`)
589				}
590				q.name = name
591			case "start", "end":
592				n, err := nextJSONNumber(dec, key)
593				if err != nil {
594					return q, err
595				}
596				v, err := parseJSONInt(n)
597				if err != nil {
598					return q, fmt.Errorf(`field %q: %s`, key, err)
599				}
600				if key == "start" {
601					q.start = v
602				} else {
603					q.end = v
604				}
605			case "labels":
606				labels, err := parseLabels(dec, `field "labels" must be an object of non-empty string keys to string values`)
607				if err != nil {
608					return q, err
609				}
610				q.labels = labels
611			}
612		}
613		if _, err := dec.Token(); err != nil { // 消耗 '}'
614			return q, err
615		}
616		if _, err := dec.Token(); err != io.EOF {
617			if err == nil {
618				return q, fmt.Errorf("unexpected content after the query object")
619			}
620			return q, err
621		}
622	
623		for _, field := range []string{"op", "name", "start", "end"} {
624			if !present[field] {
625				return q, fmt.Errorf("missing required field %q", field)
626			}
627		}
628		return q, nil
629	}
630	
631	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
632	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
633	func labelsMatch(want, stored map[string]string) bool {
634		for k, v := range want {
635			got, ok := stored[k]
636			if !ok || got != v {
637				return false
638			}
639		}
640		return true
641	}
642	
643	// runQuery 只读扫描已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
644	// 结果沿用 snapshot 的序列排序；无区间内点的序列不列出。
645	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
646		matched := make([]*storedSeries, 0)
647		for _, sr := range s.series {
648			if sr.ref.Name != q.name || !labelsMatch(q.labels, sr.ref.Labels) {
649				continue
650			}
651			has := false
652			for ts := range sr.points {
653				if ts >= q.start && ts <= q.end {
654					has = true
655					break
656				}
657			}
658			if has {
659				matched = append(matched, sr)
660			}
661		}
662		sort.Slice(matched, func(i, j int) bool {
663			if matched[i].ref.Name != matched[j].ref.Name {
664				return matched[i].ref.Name < matched[j].ref.Name
665			}
666			return compareLabelPairs(sortedPairs(matched[i].ref.Labels), sortedPairs(matched[j].ref.Labels)) < 0
667		})
668	
669		out := make([]QuerySeries, 0, len(matched))
670		for _, sr := range matched {
671			tsList := make([]int64, 0, len(sr.points))
672			for ts := range sr.points {
673				if ts >= q.start && ts <= q.end {
674					tsList = append(tsList, ts)
675				}
676			}
677			sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
678			values := make([]float64, len(tsList))
679			for i, ts := range tsList {
680				values[i] = sr.points[ts]
681			}
682			labels := cloneLabels(sr.ref.Labels)
683			out = append(out, QuerySeries{
684				Name:    sr.ref.Name,
685				Labels:  labels,
686				Count:   len(values),
687				Average: finiteMean(values),
688			})
689		}
690		return &QueryResult{Status: "ok", Op: "query", Series: out}
691	}
692	
693	// finiteMean 返回已存储 float64 值的精确算术平均所对应的最近 float64，
694	// 恰好在两个相邻可表示值中间时按最近偶数舍入。
695	// 求和用有理数精确完成：与点的顺序、批次划分无关，正负大数抵消后的小余量
696	// 不会丢失，总和超出 float64 范围时结果仍然有限。精确平均为零时返回 +0；
697	// 只有一个点时结果就是该点的值。
698	func finiteMean(values []float64) float64 {
699		sum := new(big.Rat)
700		r := new(big.Rat)
701		for _, v := range values {
702			// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
703			sum.Add(sum, r.SetFloat64(v))
704		}
705		sum.Quo(sum, r.SetInt64(int64(len(values))))
706		return ratToFloat64NearestEven(sum)
707	}
708	
709	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
710	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
711	func ratToFloat64NearestEven(x *big.Rat) float64 {
712		if x.Sign() == 0 {
713			return 0
714		}
715		num := new(big.Int).Set(x.Num())
716		den := x.Denom()
717		neg := num.Sign() < 0
718		if neg {
719			num.Neg(num)
720		}
721	
722		// e 满足 2^e <= num/den < 2^(e+1)。
723		e := floorLog2Rat(num, den)
724		var m *big.Int
725		scale := 0
726		if e >= -1022 {
727			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
728			scale = e - 52
729			m = roundScaledRatio(num, den, scale)
730			if m.BitLen() == 54 {
731				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
732				m.Rsh(m, 1)
733				scale++
734			}
735		} else {
736			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
737			scale = -1074
738			m = roundScaledRatio(num, den, scale)
739		}
740		// m < 2^53，可以精确放入 int64 与 float64。
741		f := math.Ldexp(float64(m.Int64()), scale)
742		if neg {
743			return -f
744		}
745		return f
746	}
747	
748	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
749	func floorLog2Rat(num, den *big.Int) int {
750		k := num.BitLen() - den.BitLen()
751		var t big.Int
752		if k >= 0 {
753			t.Lsh(den, uint(k))
754			if num.Cmp(&t) >= 0 {
755				return k
756			}
757			return k - 1
758		}
759		t.Lsh(num, uint(-k))
760		if t.Cmp(den) >= 0 {
761			return k
762		}
763		return k - 1
764	}
765	
766	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
767	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
768		n := new(big.Int).Set(num)
769		d := new(big.Int).Set(den)
770		if scale >= 0 {
771			d.Lsh(d, uint(scale))
772		} else {
773			n.Lsh(n, uint(-scale))
774		}
775		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
776		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
777		case 1:
778			q.Add(q, big.NewInt(1))
779		case 0:
780			if q.Bit(0) == 1 {
781				q.Add(q, big.NewInt(1))
782			}
783		}
784		return q
785	}
786	
787	// String 让冲突原因中的序列身份可读：name{k=v,...}，标签按键排序。
788	func (r SeriesRef) String() string {
789		var b strings.Builder
790		b.WriteString(r.Name)
791		b.WriteByte('{')
792		for i, p := range sortedPairs(r.Labels) {
793			if i > 0 {
794				b.WriteByte(',')
795			}
796			fmt.Fprintf(&b, "%s=%s", p.Key, p.Value)
797		}
798		b.WriteByte('}')
799		return b.String()
800	}
801	
802	// snapshot 生成按规范排序的全部序列视图：先按指标名，再按标签键值对字典序，
803	// 序列内按时间戳升序。
804	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
805		views := make([]SeriesView, 0, len(s.series))
806		for _, sr := range s.series {
807			tsList := make([]int64, 0, len(sr.points))
808			for ts := range sr.points {
809				tsList = append(tsList, ts)
810			}
811			sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
812			points := make([]Point, len(tsList))
813			for i, ts := range tsList {
814				points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
815			}
816			views = append(views, SeriesView{Name: sr.ref.Name, Labels: cloneLabels(sr.ref.Labels), Points: points})
817		}
818		sort.Slice(views, func(i, j int) bool {
819			if views[i].Name != views[j].Name {
820				return views[i].Name < views[j].Name
821			}
822			return compareLabelPairs(sortedPairs(views[i].Labels), sortedPairs(views[j].Labels)) < 0
823		})
824		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
825	}
826

