381		store := NewMetricStore()
382		mustOK(t, store, `[
383			{"name":"m","timestamp":1,"value":1},
384			{"name":"m","timestamp":1,"value":2,"labels":{"zone":""}},
385			{"name":"m","timestamp":1,"value":3,"labels":{"zone":"x"}},
386			{"name":"m","timestamp":1,"value":4,"labels":{"zone":"x","host":"h"}},
387			{"name":"other","timestamp":1,"value":9}
388		]`)
389	
390		// 省略 labels：该指标全部序列（共 4 条），不合并；顺序沿用 snapshot 排序。
391		res := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":2}`)
392		if len(res.Series) != 4 {
393			t.Fatalf("all series = %+v, want 4", res.Series)
394		}
395		wantOrder := []map[string]string{
396			{},
397			{"host": "h", "zone": "x"},
398			{"zone": ""},
399			{"zone": "x"},
400		}
401		for i, wantLabels := range wantOrder {
402			got := res.Series[i].Labels
403			if len(got) != len(wantLabels) {
404				t.Fatalf("series[%d] labels = %v, want %v", i, got, wantLabels)
405			}
406			for k, v := range wantLabels {
407				if gv, ok := got[k]; !ok || gv != v {
408					t.Fatalf("series[%d] labels = %v, want %v", i, got, wantLabels)
409				}
410			}
411		}
412	
413		// 空对象等价于省略。
414		res = mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":2,"labels":{}}`)
415		if len(res.Series) != 4 {
416			t.Fatalf("empty labels = %+v, want all 4 series", res.Series)
417		}
418	
419		// 子集匹配：zone=x 同时匹配带 host 额外标签和无额外标签的两条序列；
420		// 排序沿用 snapshot：标签对 (host,h)<(zone,x)，故带 host 的序列在前。
421		res = mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":2,"labels":{"zone":"x"}}`)
422		if len(res.Series) != 2 || res.Series[0].Average != 4 || res.Series[1].Average != 3 {
423			t.Fatalf("subset match = %+v, want averages 4 and 3", res.Series)
424		}
425	
426		// 额外约束 host 后只剩一条。
427		res = mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":2,"labels":{"zone":"x","host":"h"}}`)
428		if len(res.Series) != 1 || res.Series[0].Average != 4 {
429			t.Fatalf("fully specified match = %+v, want average 4", res.Series)
430		}
431	
432		// 空字符串只匹配真实存在的空值标签，不匹配缺少该标签的序列。
433		res = mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":2,"labels":{"zone":""}}`)
434		if len(res.Series) != 1 || res.Series[0].Average != 2 {
435			t.Fatalf("empty-value match = %+v, want single series avg 2", res.Series)
436		}
437	
438		// 要求一个不存在的标签：空结果。
439		res = mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":2,"labels":{"nope":"x"}}`)
440		if len(res.Series) != 0 {
441			t.Fatalf("missing label match = %+v, want empty", res.Series)
442		}
443	
444		// 标签顺序不影响匹配。
445		res = mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":2,"labels":{"host":"h","zone":"x"}}`)
446		if len(res.Series) != 1 {
447			t.Fatalf("label order must not matter, got %+v", res.Series)
448		}
449	
450		// name 精确匹配：不同指标不返回。
451		res = mustQuery(t, store, `{"op":"query","name":"nonexistent","start":0,"end":2}`)
452		if len(res.Series) != 0 {
453			t.Fatalf("unknown metric = %+v, want empty", res.Series)
454		}
455	
456		// 无标签序列输出为空对象而非 null。
457		b, _ := json.Marshal(res)
458		if string(b) != `{"status":"ok","op":"query","series":[]}` {
459			t.Fatalf("empty result shape = %s", b)
460		}
461		res = mustQuery(t, store, `{"op":"query","name":"other","start":0,"end":2}`)
462		if len(res.Series) != 1 || len(res.Series[0].Labels) != 0 {
463			t.Fatalf("unlabeled series = %+v", res.Series)
464		}
465		b, _ = json.Marshal(res.Series[0].Labels)
466		if string(b) != `{}` {
467			t.Fatalf("labels should serialize as {}, got %s", b)
468		}
469	}
